using System.Security.Cryptography;
using MeowChan.Archive;
using MeowChan.Interfaces;
using MeowChan.Persistence;

namespace MeowChan.Tests.PersistenceCorruption;

/// <summary>
/// PF-R4: files that the released 1.0.2 stores wrote, as fixed bytes (tests/Fixtures/persistence102, generated by
/// tests/fixtures/persistence-v1.0.2 from the code of tag v1.0.2, revision eec6c0169f8d52f7481ea0bf7febfd20981e97c3). The
/// round-trip tests of the corruption suite write with the current code, so they cannot notice that a newly required member
/// refuses what 1.0.2 really wrote; these do. Each file is pinned by SHA-256, so editing one by hand fails here first.
/// </summary>
public sealed class Release102FixtureTests
{
    private static readonly Dictionary<string, string> Digests = new()
    {
        ["reader-groups.json"] = "b4b93ba8e00cd46a2cf819b375a40ab741558e89aff44ed8bb222f31fc3009c7",
        ["reader-groups.json.bak"] = "88565cc348e3ddc831575a38502752dd5800267c235447db9fa4c297b2bf5a77",
        ["reader-groups-emptied.json"] = "7411bd0b2f1bd5a7ea2866913602c0b9d7e6dc456eba4624364bc97123289b91",
        ["archive-searches.json"] = "7e4c6b80575e3cfd73d9ff5d621f83d5b2f66b8c69e23f6f7642416bf1c7d379",
        ["archive-searches.json.bak"] = "7082fb208ccd41bdb87c17746619ae02b692e0840ac73c4ad3df53c9ee4dfb07"
    };

    private static readonly Guid GroupBoth = Guid.Parse("1a0251a0-0000-4000-8000-000000000011");
    private static readonly Guid GroupEmpty = Guid.Parse("1a0251a0-0000-4000-8000-000000000012");
    private static readonly Guid GroupEscaped = Guid.Parse("1a0251a0-0000-4000-8000-000000000013");
    private static readonly Guid Search1 = Guid.Parse("1a0251a0-0000-4000-8000-000000000001");
    private static readonly Guid Search2 = Guid.Parse("1a0251a0-0000-4000-8000-000000000002");
    private static readonly Guid Search3 = Guid.Parse("1a0251a0-0000-4000-8000-000000000003");

    private static byte[] Fixture(string name)
    {
        using Stream stream = typeof(Release102FixtureTests).Assembly.GetManifestResourceStream("persistence102/" + name)
            ?? throw new FileNotFoundException("Missing embedded fixture " + name);
        using MemoryStream bytes = new();
        stream.CopyTo(bytes);
        return bytes.ToArray();
    }

    private static void Place(string directory, string fixture, string target) => File.WriteAllBytes(Path.Combine(directory, target), Fixture(fixture));

    private static T Run<T>(Func<Task<T>> work) => Task.Run(work).GetAwaiter().GetResult();

    [Theory]
    [MemberData(nameof(Names))]
    public void TheFixtureBytesAreTheOnesThatWereGenerated(string name) =>
        Assert.Equal(Digests[name], Convert.ToHexStringLower(SHA256.HashData(Fixture(name))));

    public static IEnumerable<object[]> Names() => Digests.Keys.Select(name => new object[] { name });

    [Fact]
    public void Reader102GroupsFileLoadsWithAllItsGroups()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        Place(temp.Path, "reader-groups.json", "reader-groups.json");
        Place(temp.Path, "reader-groups.json.bak", "reader-groups.json.bak");

        ReaderGroupsLoadResult loaded = Run(() => new ReaderGroupStore(temp.Path, lease).LoadAsync());

        Assert.Equal(ReaderGroupsLoadState.Ready, loaded.State);
        Assert.Equal(2, loaded.Snapshot!.Revision);
        Assert.Equal([GroupBoth, GroupEmpty, GroupEscaped], loaded.Snapshot.Groups.Select(group => group.Id));
        Assert.Equal(["both sources", "empty group", "café \"quoted\" \\ 😀"], loaded.Snapshot.Groups.Select(group => group.Name));
        Assert.Equal([new ResourceId("4chan", "g", "123"), new ResourceId("8kun", "g", "123"), new ResourceId("4chan", "a", "9")], loaded.Snapshot.Groups[0].Members);
        Assert.Empty(loaded.Snapshot.Groups[1].Members);
        Assert.Equal([new ResourceId("8kun", "g", "123")], loaded.Snapshot.Groups[2].Members);
    }

    [Fact]
    public void Reader102GroupsEmptiedByLoadsAsAnEmptyListAtItsRevisionNotAsDamage()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        Place(temp.Path, "reader-groups-emptied.json", "reader-groups.json");

        ReaderGroupsLoadResult loaded = Run(() => new ReaderGroupStore(temp.Path, lease).LoadAsync());

        Assert.Equal(ReaderGroupsLoadState.Ready, loaded.State);
        Assert.Equal(2, loaded.Snapshot!.Revision);
        Assert.Empty(loaded.Snapshot.Groups);
    }

    [Fact]
    public void Reader102GroupsBackupIsOfferedWhenThePrimaryIsDamagedAndRestoresItsGroup()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        byte[] primary = Fixture("reader-groups.json");
        File.WriteAllBytes(Path.Combine(temp.Path, "reader-groups.json"), primary[..(primary.Length / 2)]);
        Place(temp.Path, "reader-groups.json.bak", "reader-groups.json.bak");
        ReaderGroupStore store = new(temp.Path, lease);

        ReaderGroupsLoadResult loaded = Run(() => store.LoadAsync());

        Assert.Equal(ReaderGroupsLoadState.RecoveryAvailable, loaded.State);
        Assert.Equal(1, loaded.Snapshot!.Revision);
        ReaderGroup only = Assert.Single(loaded.Snapshot.Groups);
        Assert.Equal("first generation", only.Name);
        ReaderGroupsSnapshot restored = Run(() => store.RestoreBackupAsync(loaded.RecoveryToken!));
        Assert.Equal(2, restored.Revision);
    }

    [Fact]
    public void Reader102GroupsOfCanBeEditedByTheCurrentCodeAndStillLoad()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        Place(temp.Path, "reader-groups.json", "reader-groups.json");
        Place(temp.Path, "reader-groups.json.bak", "reader-groups.json.bak");
        ReaderGroupStore store = new(temp.Path, lease);
        ReaderGroupsLoadResult loaded = Run(() => store.LoadAsync());

        ReaderGroupsSnapshot saved = Run(() => store.SaveAsync(loaded.Snapshot! with
            { Groups = loaded.Snapshot.Groups.Where(group => group.Id != GroupEmpty).ToArray() }, loaded.Snapshot.Revision));

        Assert.Equal(3, saved.Revision);
        // The 1.0.2 primary became the backup, byte for byte.
        Assert.Equal(Fixture("reader-groups.json"), File.ReadAllBytes(Path.Combine(temp.Path, "reader-groups.json.bak")));
        ReaderGroupsLoadResult reloaded = Run(() => new ReaderGroupStore(temp.Path, lease).LoadAsync());
        Assert.Equal(ReaderGroupsLoadState.Ready, reloaded.State);
        Assert.Equal([GroupBoth, GroupEscaped], reloaded.Snapshot!.Groups.Select(group => group.Id));
    }

    [Fact]
    public void TheCurrentWriterStillWritesTheBytesOf102ForTheSameGroups()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        ReaderGroupStore store = new(temp.Path, lease);
        ReaderGroupsSnapshot first = Run(() => store.SaveAsync(new ReaderGroupsSnapshot(1, 0, new[]
        {
            new ReaderGroup(Guid.Parse("1a0251a0-0000-4000-8000-000000000021"), "first generation", new[] { new ResourceId("4chan", "g", "123") })
        }), 0));
        Run(() => store.SaveAsync(new ReaderGroupsSnapshot(1, first.Revision, new[]
        {
            new ReaderGroup(GroupBoth, "both sources", new[] { new ResourceId("4chan", "g", "123"), new ResourceId("8kun", "g", "123"), new ResourceId("4chan", "a", "9") }),
            new ReaderGroup(GroupEmpty, "empty group", Array.Empty<ResourceId>()),
            new ReaderGroup(GroupEscaped, "café \"quoted\" \\ 😀", new[] { new ResourceId("8kun", "g", "123") })
        }), first.Revision));

        Assert.Equal(Fixture("reader-groups.json"), File.ReadAllBytes(Path.Combine(temp.Path, "reader-groups.json")));
        Assert.Equal(Fixture("reader-groups.json.bak"), File.ReadAllBytes(Path.Combine(temp.Path, "reader-groups.json.bak")));
    }

    [Fact]
    public void Saved102SearchesLoadWithEveryDefinitionApplicable()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        Place(temp.Path, "archive-searches.json", "archive-searches.json");
        Place(temp.Path, "archive-searches.json.bak", "archive-searches.json.bak");

        SavedArchiveSearchSnapshot loaded = new SavedArchiveSearchStore(temp.Path, lease).Load();

        Assert.Equal(SavedSearchStoreState.Ready, loaded.State);
        Assert.True(loaded.CanWrite);
        Assert.Equal(4, loaded.Revision);
        Assert.Equal([Search1, Search2, Search3], loaded.Searches.Select(search => search.Id));
        Assert.Equal(["plain text and source (renamed)", "board in every source", "everything set"], loaded.Searches.Select(search => search.Name));
        Assert.All(loaded.Searches, search => { Assert.True(search.CanApply); Assert.Null(search.UnsupportedReason); });
        ArchiveSearchSpec all = loaded.Searches[2].Definition!;
        Assert.Equal("café \"quoted\" \\ 😀", all.Text);
        Assert.Equal(["4chan", "8kun"], all.Sources);
        Assert.True(all.CaptureEnabled);
        Assert.False(all.HasPosts);
        Assert.Equal(ArchiveThreadSort.Title, all.Sort);
        Assert.Equal(ArchiveWorkFilter.Watching, all.WorkFilter);
        Assert.Equal(new ArchiveDateRange(new DateOnly(2026, 1, 2), new DateOnly(2026, 3, 4), "UTC"), all.DateRange);
        Assert.Equal([ThreadSourceState.Archived, ThreadSourceState.NotFound], loaded.Searches[1].Definition!.SourceStates);
        Assert.Equal([new ArchiveBoardConstraint(null, "a"), new ArchiveBoardConstraint("8kun", "g")], loaded.Searches[1].Definition!.Boards);
    }

    [Fact]
    public void Saved102SearchesBackupIsOfferedWhenThePrimaryIsDamaged()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        byte[] primary = Fixture("archive-searches.json");
        File.WriteAllBytes(Path.Combine(temp.Path, "archive-searches.json"), primary[..(primary.Length / 2)]);
        Place(temp.Path, "archive-searches.json.bak", "archive-searches.json.bak");

        SavedArchiveSearchSnapshot loaded = new SavedArchiveSearchStore(temp.Path, lease).Load();

        Assert.Equal(SavedSearchStoreState.RecoveryAvailable, loaded.State);
        Assert.Equal(3, loaded.Revision);
        Assert.Equal("plain text and source", loaded.Searches.First(search => search.Id == Search1).Name);
    }

    [Fact]
    public void Saved102SearchesCanBeEditedByTheCurrentCodeAndStillLoad()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        Place(temp.Path, "archive-searches.json", "archive-searches.json");
        Place(temp.Path, "archive-searches.json.bak", "archive-searches.json.bak");
        SavedArchiveSearchStore store = new(temp.Path, lease);
        SavedArchiveSearchSnapshot loaded = store.Load();

        SavedArchiveSearchSnapshot saved = store.Delete(Search2, loaded.Revision);

        Assert.Equal(5, saved.Revision);
        Assert.Equal(Fixture("archive-searches.json"), File.ReadAllBytes(Path.Combine(temp.Path, "archive-searches.json.bak")));
        SavedArchiveSearchSnapshot reloaded = new SavedArchiveSearchStore(temp.Path, lease).Load();
        Assert.Equal(SavedSearchStoreState.Ready, reloaded.State);
        Assert.Equal([Search1, Search3], reloaded.Searches.Select(search => search.Id));
    }

    [Fact]
    public void TheCurrentWriterStillWritesTheBytesOf102ForTheSameSearches()
    {
        using TempDirectory temp = new();
        using ProfileLease lease = ProfileLease.Acquire(temp.Path);
        SavedArchiveSearchStore store = new(temp.Path, lease);
        SavedArchiveSearchSnapshot state = store.Load();
        state = store.Create(Search1, "plain text and source", new ArchiveSearchSpec("retained", new[] { "4chan" }), state.Revision);
        state = store.Create(Search2, "board in every source",
            new ArchiveSearchSpec("reply", boards: new[] { new ArchiveBoardConstraint("8kun", "g"), new ArchiveBoardConstraint(null, "a") },
                sourceStates: new[] { ThreadSourceState.Archived, ThreadSourceState.NotFound }), state.Revision);
        state = store.Create(Search3, "everything set",
            new ArchiveSearchSpec("café \"quoted\" \\ 😀", new[] { "4chan", "8kun" }, captureEnabled: true, hasPosts: false,
                sort: ArchiveThreadSort.Title, workFilter: ArchiveWorkFilter.Watching,
                dateRange: new ArchiveDateRange(new DateOnly(2026, 1, 2), new DateOnly(2026, 3, 4), "UTC")), state.Revision);
        store.Rename(Search1, "plain text and source (renamed)", state.Revision);

        Assert.Equal(Fixture("archive-searches.json"), File.ReadAllBytes(Path.Combine(temp.Path, "archive-searches.json")));
        Assert.Equal(Fixture("archive-searches.json.bak"), File.ReadAllBytes(Path.Combine(temp.Path, "archive-searches.json.bak")));
    }
}
